local ClientPlayer

---@return CBasePlayer
function PidPacketSender:ClientPlayer()
    if not ClientPlayer then
        ClientPlayer = PlayerManager:getClientPlayer()
    end
    return ClientPlayer
end

---@param packet PidPacket
function PidPacketSender:sendPacket(packet, resp)
    self:ClientPlayer():sendPacket(packet, resp)
end

function PidPacketSender:SyncBlockmanSkins()
    if not isLocalWin then
        return
    end
    WebService.GetPlayerDecoration(Game:getPlatformUserId(), function(skins)
        self:sendPacket({
            pid = "SyncBlockmanSkins",
            skins = skins,
        })
    end)
end

function PidPacketSender:onWatchAdSuccess(type, params)
    self:sendPacket({
        pid = "onWatchAdSuccess",
        type = type,
        params = params,
    })
end

